"""Measure an original-frame left-turn sequence without making a legal finding.

The input is a saved actor readback, not an authored motion request. The local
capture must seal its Native source before this measurement is used for delivery.
"""
import argparse
import hashlib
import json
import math
from pathlib import Path


FRAMES = 600
RATE_HZ = 20
ASSIGNMENT = "training__C329654__NRS-484B-253__motor_vehicle_driver"
CASES = {ASSIGNMENT + "__selected_d457f261__condition_a",
         ASSIGNMENT + "__selected_d457f261__condition_b"}


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def finite(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def measure(path):
    path = Path(path)
    records = [json.loads(line) for line in path.read_text().splitlines()]
    if len(records) != FRAMES:
        raise ValueError("Complete 600-frame observed actor source required")
    case_id = records[0].get("case_id")
    if case_id not in CASES:
        raise ValueError("Exact selected case identity differs")
    source_kind = records[0].get("source_kind")
    if source_kind not in ("original_native", "synthetic_cpu"):
        raise ValueError("Observed actor source provenance required")
    actor_ids = None
    native_frames = []
    for frame, row in enumerate(records):
        if row.get("case_id") != case_id or row.get("source_kind") != source_kind:
            raise ValueError("Case or provenance changes within observed source")
        if row.get("frame") != frame or not finite(row.get("time_s")) or abs(row["time_s"] - frame / RATE_HZ) > 1e-6:
            raise ValueError("Observed frame and time join differs")
        native = row.get("native_frame")
        if not isinstance(native, int) or isinstance(native, bool):
            raise ValueError("Missing original Native frame readback")
        native_frames.append(native)
        ego = row.get("ego", {})
        if not all(finite(ego.get(key)) for key in ("speed_mps", "left_turn_progress", "distance_to_conflict_m")):
            raise ValueError("Missing measured ego kinematics")
        if not 0 <= ego["left_turn_progress"] <= 1 or ego["speed_mps"] < 0:
            raise ValueError("Invalid measured ego kinematics")
        if ego.get("inside_intersection") not in (True, False) or ego.get("left_indicator_on") not in (True, False):
            raise ValueError("Missing original intersection or lamp readback")
        opponents = row.get("oncoming")
        if not isinstance(opponents, list) or len(opponents) < 2:
            raise ValueError("Initial and subsequent opposing actors required")
        ids = tuple(item.get("actor_id") for item in opponents)
        if len(set(ids)) != len(ids) or any(not isinstance(item, str) or not item for item in ids):
            raise ValueError("Opposing actor identity differs")
        if actor_ids is None:
            actor_ids = ids
        elif actor_ids != ids:
            raise ValueError("Opposing actor identity changes within source")
        for opponent in opponents:
            if not all(finite(opponent.get(key)) for key in ("speed_mps", "distance_to_conflict_m")):
                raise ValueError("Missing opposing actor kinematics")
            if opponent["speed_mps"] < 0 or opponent.get("approach_lane_opposite") is not True:
                raise ValueError("Opposing lane or speed readback differs")
    if any(b <= a for a, b in zip(native_frames, native_frames[1:])):
        raise ValueError("Original Native frame sequence is not increasing")
    turn = next((i for i, row in enumerate(records)
                 if row["ego"]["left_turn_progress"] > 0), None)
    if turn is None:
        raise ValueError("Measured left turn never starts")
    if not records[turn]["ego"]["inside_intersection"] or not all(
            row["ego"]["left_indicator_on"] for row in records[max(0, turn - 20):turn + 1]):
        raise ValueError("Measured intersection presence or signal is absent at turn")
    first_pass = next((i for i, row in enumerate(records)
                       if row["oncoming"][0]["distance_to_conflict_m"] <= 0), None)
    if first_pass is None:
        raise ValueError("Initial opponent never reaches conflict point")
    second_pass = next((i for i, row in enumerate(records)
                        if row["oncoming"][1]["distance_to_conflict_m"] <= 0), None)
    stopped_before_turn = any(row["ego"]["speed_mps"] < 0.1 for row in records[100:turn])
    if not stopped_before_turn:
        raise ValueError("No measured preturn yielding wait")
    second_speed_at_turn = records[turn]["oncoming"][1]["speed_mps"]
    later_second_speed = min(row["oncoming"][1]["speed_mps"] for row in records[turn:])
    return {
        "format": "c329654-observed-left-turn-v1", "case_id": case_id,
        "source_kind": source_kind, "source_sha256": digest(path),
        "frames": FRAMES, "rate_hz": RATE_HZ,
        "first_turn_progress_frame": turn,
        "first_opponent_conflict_frame": first_pass,
        "subsequent_opponent_conflict_frame": second_pass,
        "initial_opponent_passed_before_turn": first_pass < turn,
        "subsequent_opponent_speed_at_turn_mps": second_speed_at_turn,
        "subsequent_opponent_min_speed_after_turn_mps": later_second_speed,
        "subsequent_opponent_decelerated_after_turn": later_second_speed < second_speed_at_turn,
        "preturn_wait_observed": stopped_before_turn,
        "turn_signal_observed_before_and_at_turn": True,
        "subsequent_yield_response_observed": later_second_speed < second_speed_at_turn,
        "legal_immediate_hazard_threshold_asserted": False,
        "legal_priority_verdict": None,
        "physical_acceptance_claimed": False,
    }


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", required=True)
    args = parser.parse_args()
    print(json.dumps(measure(args.source), sort_keys=True))

"""Native actor readback for the exact left-turn interaction.

The local runner supplies original CARLA actors and a map survey. This module
only samples those objects; it does not infer a legal right of way or substitute
requested controls for observed motion.
"""
from __future__ import annotations

import math


def _number(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError("Missing finite original " + label)
    return float(value)


def _xy(value, label):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("Missing original " + label)
    return (_number(value[0], label), _number(value[1], label))


def _dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def _inside(point, polygon):
    if not isinstance(polygon, list) or len(polygon) < 3:
        raise ValueError("Missing surveyed intersection polygon")
    vertices = [_xy(v, "intersection vertex") for v in polygon]
    signs = []
    for a, b in zip(vertices, vertices[1:] + vertices[:1]):
        cross = (b[0] - a[0]) * (point[1] - a[1]) - (b[1] - a[1]) * (point[0] - a[0])
        if abs(cross) > 1e-7:
            signs.append(cross > 0)
    if signs and len(set(signs)) != 1:
        return False
    return True


def _kinematics(actor):
    pose = actor.get_transform()
    velocity = actor.get_velocity()
    point = (_number(pose.location.x, "actor x"), _number(pose.location.y, "actor y"))
    speed = math.sqrt(sum(_number(getattr(velocity, axis), "velocity") ** 2 for axis in ("x", "y", "z")))
    heading = _number(pose.rotation.yaw, "actor heading")
    if not isinstance(actor.id, int) or isinstance(actor.id, bool) or actor.id <= 0:
        raise ValueError("Missing original actor identity")
    return point, speed, heading


def _distance_to_conflict(point, conflict, direction):
    return _dot((conflict[0] - point[0], conflict[1] - point[1]), direction)


def sample(native_frame, frame, time_s, case_id, ego, initial, subsequent,
           survey, left_blinker_mask, source_kind="original_native", native_map=None):
    """Sample three live actors using a measured map survey and native frame.

    `survey` is a retained Native map readback. Its opposing lane direction must
    be checked against the ego approach before any source row is emitted.
    """
    if source_kind not in ("original_native", "synthetic_cpu"):
        raise ValueError("Observed source provenance differs")
    if source_kind == "original_native" and native_map is None:
        raise ValueError("Original Native map readback required")
    if type(native_frame) is not int or native_frame < 0 or type(frame) is not int or frame < 0:
        raise ValueError("Missing Native frame identity")
    t = _number(time_s, "time")
    if abs(t - frame / 20) > 0.051:
        raise ValueError("Original frame and time drift")
    conflict = _xy(survey.get("conflict_xy_m"), "conflict point")
    survey_sha = survey.get("source_sha256")
    if not isinstance(survey_sha, str) or len(survey_sha) != 64 or any(
            char not in "0123456789abcdef" for char in survey_sha):
        raise ValueError("Missing source-hashed Native map survey")
    approach = _xy(survey.get("ego_approach_direction_xy"), "ego approach")
    opposite = _xy(survey.get("opposing_approach_direction_xy"), "opposing approach")
    route_start = _xy(survey.get("turn_start_xy_m"), "turn start")
    route_end = _xy(survey.get("turn_end_xy_m"), "turn end")
    if any(abs(math.hypot(*direction) - 1) > 0.05 for direction in (approach, opposite)):
        raise ValueError("Original approach directions are not unit vectors")
    if _dot(approach, opposite) > -0.8:
        raise ValueError("Opposing lane is not opposite to subject approach")
    if not all(isinstance(actor.id, int) for actor in (ego, initial, subsequent)) or len(
            {ego.id, initial.id, subsequent.id}) != 3:
        raise ValueError("Three distinct original actor identities required")
    start_to_end = (route_end[0] - route_start[0], route_end[1] - route_start[1])
    route_length_sq = _dot(start_to_end, start_to_end)
    if route_length_sq < 4:
        raise ValueError("Surveyed left turn route is too short")
    ego_point, ego_speed, ego_heading = _kinematics(ego)
    progress = max(0.0, min(1.0, _dot((ego_point[0] - route_start[0],
                                      ego_point[1] - route_start[1]), start_to_end) / route_length_sq))
    if not isinstance(left_blinker_mask, int) or left_blinker_mask <= 0:
        raise ValueError("Original left blinker mask missing")
    lamp = int(ego.get_light_state()) & left_blinker_mask != 0
    opponents = []
    for actor in (initial, subsequent):
        point, speed, heading = _kinematics(actor)
        lane = None
        if native_map is not None:
            lane = native_map.get_waypoint(actor.get_transform().location,
                                           project_to_road=False)
            if lane is None:
                raise ValueError("Original opposing actor lane readback absent")
            lane_heading = math.radians(_number(lane.transform.rotation.yaw, "lane heading"))
            if _dot((math.cos(lane_heading), math.sin(lane_heading)), opposite) < 0.8:
                raise ValueError("Original opposing lane direction differs")
        opponents.append({"actor_id": str(actor.id), "speed_mps": speed,
                          "distance_to_conflict_m": _distance_to_conflict(point, conflict, opposite),
                          "center_xy_m": list(point), "heading_deg": heading,
                          "approach_lane_opposite": True,
                          "native_road_id": None if lane is None else lane.road_id,
                          "native_lane_id": None if lane is None else lane.lane_id})
    return {"case_id": case_id, "source_kind": source_kind,
            "frame": frame, "native_frame": native_frame, "time_s": t,
            "ego": {"speed_mps": ego_speed, "left_turn_progress": progress,
                    "distance_to_conflict_m": _distance_to_conflict(ego_point, conflict, approach),
                    "inside_intersection": _inside(ego_point, survey.get("intersection_polygon_xy_m")),
                    "left_indicator_on": lamp, "center_xy_m": list(ego_point),
                    "heading_deg": ego_heading},
            "oncoming": opponents, "survey_source_sha256": survey_sha,
            "legal_verdict": None}

import copy
import math
import unittest
from types import SimpleNamespace

from source_capture import sample


def actor(identity, x, y, yaw=0, speed=4, lamp=1):
    class Fake:
        id = identity
        def get_transform(self):
            return SimpleNamespace(location=SimpleNamespace(x=x, y=y), rotation=SimpleNamespace(yaw=yaw))
        def get_velocity(self):
            return SimpleNamespace(x=speed, y=0, z=0)
        def get_light_state(self):
            return lamp
    return Fake()


class SourceCaptureTest(unittest.TestCase):
    def setUp(self):
        self.survey = {"conflict_xy_m": [0, 0], "ego_approach_direction_xy": [1, 0],
                       "opposing_approach_direction_xy": [-1, 0],
                       "turn_start_xy_m": [-2, 0], "turn_end_xy_m": [0, 12],
                       "intersection_polygon_xy_m": [[-4, -4], [4, -4], [4, 4], [-4, 4]],
                       "source_sha256": "a" * 64}
        self.ego, self.initial, self.subsequent = actor(1, -2, 0), actor(2, 10, 0), actor(3, 20, 0)

    def row(self, survey=None, ego=None, initial=None, subsequent=None):
        return sample(100, 100, 5, "case", ego or self.ego, initial or self.initial,
                      subsequent or self.subsequent, survey or self.survey, 1, "synthetic_cpu")

    def test_original_actor_sample(self):
        row = self.row()
        self.assertEqual(row["native_frame"], 100)
        self.assertTrue(row["ego"]["inside_intersection"])
        self.assertTrue(row["ego"]["left_indicator_on"])
        self.assertEqual([o["distance_to_conflict_m"] for o in row["oncoming"]], [10, 20])
        self.assertEqual([o["actor_id"] for o in row["oncoming"]], ["2", "3"])

    def test_original_source_requires_map_and_lane_direction(self):
        with self.assertRaisesRegex(ValueError, "map readback"):
            sample(100, 100, 5, "case", self.ego, self.initial,
                   self.subsequent, self.survey, 1)
        class Map:
            def __init__(self, yaw): self.yaw = yaw
            def get_waypoint(self, location, project_to_road=False):
                return SimpleNamespace(road_id=4, lane_id=-1,
                    transform=SimpleNamespace(rotation=SimpleNamespace(yaw=self.yaw)))
        row = sample(100, 100, 5, "case", self.ego, self.initial,
                     self.subsequent, self.survey, 1, native_map=Map(180))
        self.assertEqual([o["native_road_id"] for o in row["oncoming"]], [4, 4])
        with self.assertRaisesRegex(ValueError, "lane direction differs"):
            sample(100, 100, 5, "case", self.ego, self.initial,
                   self.subsequent, self.survey, 1, native_map=Map(0))

    def test_opposing_lane_rejected(self):
        survey = copy.deepcopy(self.survey)
        survey["opposing_approach_direction_xy"] = [1, 0]
        with self.assertRaisesRegex(ValueError, "not opposite"):
            self.row(survey=survey)

    def test_missing_actor_rejected(self):
        with self.assertRaisesRegex(ValueError, "distinct"):
            self.row(subsequent=actor(2, 20, 0))

    def test_absent_lamp_is_measured_absent(self):
        row = self.row(ego=actor(1, -2, 0, lamp=0))
        self.assertFalse(row["ego"]["left_indicator_on"])

    def test_nonfinite_velocity_rejected(self):
        with self.assertRaisesRegex(ValueError, "finite original velocity"):
            self.row(initial=actor(2, 10, 0, speed=math.nan))

    def test_missing_intersection_polygon_rejected(self):
        survey = copy.deepcopy(self.survey)
        del survey["intersection_polygon_xy_m"]
        with self.assertRaisesRegex(ValueError, "surveyed intersection"):
            self.row(survey=survey)

    def test_unsigned_survey_rejected(self):
        survey = copy.deepcopy(self.survey)
        del survey["source_sha256"]
        with self.assertRaisesRegex(ValueError, "source-hashed"):
            self.row(survey=survey)

    def test_frame_drift_rejected(self):
        with self.assertRaisesRegex(ValueError, "frame and time drift"):
            sample(100, 100, 7, "case", self.ego, self.initial,
                   self.subsequent, self.survey, 1, "synthetic_cpu")


